import * as THREE from './vendor/three.module.js';
const canvas=document.querySelector('#cook-canvas'),surface=document.querySelector('#gesture-surface');let renderer;
try{renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:false,powerPreference:'low-power'});setup()}catch(error){document.querySelector('#gesture-guide').textContent='Swipe to cook · or use the action button';console.warn('Cooking illustration mode:',error.message)}
function setup(){renderer.setPixelRatio(1);renderer.outputColorSpace=THREE.SRGBColorSpace;const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(38,1,.1,40);scene.add(new THREE.HemisphereLight(0xffe6b1,0x34433b,1.35));const sun=new THREE.DirectionalLight(0xffc96c,2.1);sun.position.set(-3,7,4);scene.add(sun);const back=new THREE.DirectionalLight(0x7e9fb6,.5);back.position.set(4,3,-3);scene.add(back);
function tex(a,b){const c=document.createElement('canvas');c.width=c.height=32;const g=c.getContext('2d');g.fillStyle=a;g.fillRect(0,0,32,32);g.fillStyle=b;for(let i=0;i<120;i++)g.fillRect((i*13)%32,(i*19)%32,2,2);const t=new THREE.CanvasTexture(c);t.magFilter=t.minFilter=THREE.NearestFilter;t.colorSpace=THREE.SRGBColorSpace;return t}
const material=(color,map)=>new THREE.MeshStandardMaterial({color,roughness:.85,flatShading:true,map:map||null});const iron=material(0xffffff,tex('#484038','#292a29')),wood=material(0xffffff,tex('#9e6838','#b78043')),cream=material(0xead3a0),broth=material(0xffffff,tex('#a96f22','#cd9437')),red=material(0xad3721),green=material(0x6e8a30),garlic=material(0xd6c394),butter=material(0xf0c75f),yellow=material(0xe1ac33);const mushMat=material(0xe0c597,tex('#f0d3a0','#b99366')),mushBrown=material(0xb57732,tex('#d29845','#7c4924'));const geos={box:new THREE.BoxGeometry(1,1,1),ball:new THREE.IcosahedronGeometry(1,1),disk:new THREE.CylinderGeometry(1,1,.08,16),cap:new THREE.SphereGeometry(.24,7,4,0,Math.PI*2,0,Math.PI/2),chili:new THREE.TorusGeometry(.16,.055,4,9)};
function add(geo,m,x,y,z,sx=1,sy=1,sz=1,parent=scene){const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);parent.add(o);return o}const root=new THREE.Group();scene.add(root);const pan=new THREE.Group();root.add(pan);add(new THREE.CylinderGeometry(2.35,2.05,.3,24),iron,0,0,0,1,1,1,pan);add(new THREE.TorusGeometry(2.24,.12,5,24),iron,0,.18,0,1,1,1,pan).rotation.x=Math.PI/2;add(geos.box,wood,0,-.02,3.05,.45,.22,2.05,pan);add(geos.box,iron,0,-.01,2.2,.35,.2,.8,pan);
const board=new THREE.Group();root.add(board);add(geos.box,wood,0,-.04,0,5,.22,3.3,board);for(let i=-2;i<=2;i++)add(geos.box,material(0x85552d),i,.085,0,.02,.015,3.2,board);
const bowl=new THREE.Group();root.add(bowl);add(new THREE.CylinderGeometry(2.1,1.45,.95,16),cream,0,0,0,1,1,1,bowl);add(new THREE.CylinderGeometry(1.72,1.66,.08,16),material(0x4b6264),0,-.14,0,1,1,1,bowl);add(new THREE.TorusGeometry(2.02,.13,5,20),cream,0,.51,0,1,1,1,bowl).rotation.x=Math.PI/2;add(new THREE.CylinderGeometry(1.93,1.93,.04,20),broth,0,.5,0,1,1,1,bowl);const noodleMat=material(0xe8c37c);for(let i=0;i<12;i++){const n=add(new THREE.TorusGeometry(.6+i*.03,.045,4,12,Math.PI*1.8),noodleMat,Math.sin(i)*.5,.55+Math.random()*.04,Math.cos(i)*.5,1,1,1,bowl);n.rotation.x=Math.PI/2;n.rotation.z=i}
const foodRoot=new THREE.Group();root.add(foodRoot);let food=[],foodKey='',stage='',cutKick=0,tossKick=0;const spatula=new THREE.Group();root.add(spatula);add(geos.box,wood,0,.65,1.4,.22,.14,2.4,spatula);add(geos.box,wood,0,.65,.02,.72,.12,.9,spatula);for(let i=-1;i<=1;i++)add(geos.box,iron,i*.2,.716,.02,.055,.005,.55,spatula);
const knife=new THREE.Group();root.add(knife);add(geos.box,material(0xa6b2ad),0,.65,0,1.6,.5,.08,knife);add(geos.box,wood,1.2,.65,0,.8,.22,.18,knife);
function foodModel(id,index){const g=new THREE.Group();const a=index*2.4,r=.45+(index%5)*.29;g.position.set(Math.cos(a)*r,.25,Math.sin(a)*r);g.userData={base:g.position.clone(),id};if(id===1){add(geos.cap,mushMat,0,.1,0,1.6,1.1,1.5,g);add(geos.box,cream,0,0,0,.15,.23,.14,g)}else if(id===2){for(let j=0;j<3;j++){const leaf=add(geos.ball,green,j*.1,.05,0,.28,.05,.12,g);leaf.rotation.y=j*1.2}}else if(id===3){add(geos.chili,red,0,.1,0,1,1,1,g).rotation.x=Math.PI/2;add(geos.ball,cream,.08,.14,.04,.03,.02,.03,g)}else if(id===4){add(geos.disk,cream,0,.08,0,.32,1,.25,g);add(geos.disk,yellow,0,.13,0,.14,1,.13,g)}else if(id===5)add(geos.box,butter,0,.08,0,.35,.18,.3,g);else if(id===6){for(let j=0;j<5;j++)add(geos.ball,yellow,(j%3)*.12,.08,Math.floor(j/3)*.13,.075,.07,.08,g)}else add(geos.ball,garlic,0,.08,0,.15,.1,.18,g);foodRoot.add(g);return g}
function rebuild(s){while(foodRoot.children.length)foodRoot.remove(foodRoot.children[0]);food=[];let index=0;for(const id of s.recipe.filter(i=>i!==0)){const count=s.stage==='choose'?3:s.stage==='slice'?Math.min(7,2+Math.floor(s.slices/2)):7;for(let j=0;j<count;j++)food.push(foodModel(id,index++))}foodKey=s.recipe.join()+'|'+(s.stage==='slice'?Math.floor(s.slices/2):'cooked')}
const steam=[];for(let i=0;i<12;i++)steam.push(add(geos.ball,new THREE.MeshBasicMaterial({color:0xf6dfbc,transparent:true,opacity:.2,depthWrite:false}),0,1,0,.07,.1,.07));
window.cookView={cut(){cutKick=1;window.cookAudio?.tap()},stir(){tossKick=1}};function resize(){const w=surface.clientWidth,h=surface.clientHeight;if(!w||!h)return;renderer.setSize(Math.round(w*.85),Math.round(h*.85),false);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(surface);let previous=performance.now(),time=0;
function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-previous)/1000,.05);previous=now;const s=window.cookState;if(window.cookAudio)window.cookAudio.fry(!!s?.active&&!s.paused&&!document.hidden&&s.stage==='fry');if(!s?.active||document.hidden)return;if(!s.paused){time+=dt;cutKick=Math.max(0,cutKick-dt*5);tossKick=Math.max(0,tossKick-dt*2)}const key=s.recipe.join()+'|'+(s.stage==='slice'?Math.floor(s.slices/2):'cooked');if(key!==foodKey)rebuild(s);if(stage!==s.stage){stage=s.stage;resize()}const slicing=s.stage==='slice',tasting=s.stage==='taste';board.visible=slicing||s.stage==='choose';pan.visible=s.stage==='fry';bowl.visible=tasting;knife.visible=slicing;spatula.visible=s.stage==='fry';camera.position.set(0,slicing?6.8:tasting?4.5:7.5,slicing?3.4:tasting?6.2:2.6);camera.lookAt(0,0,0);camera.fov=tasting?44:47;camera.updateProjectionMatrix();knife.position.set(s.tool?.x||0,Math.sin(cutKick*Math.PI)*.7,s.tool?.y||0);knife.rotation.z=-.2+Math.sin(cutKick*Math.PI)*.5;spatula.position.set((s.tool?.x||0)*1.5,.25,(s.tool?.y||0)*1.4);spatula.rotation.y=-.5+(s.tool?.x||0)*.5;
food.forEach((g,i)=>{const base=g.userData.base,a=time*.2+i;const stir=Math.sin(tossKick*Math.PI);g.position.x=base.x+Math.sin(a*4)*stir*.28;g.position.z=base.z+Math.cos(a*4)*stir*.28;g.position.y=(tasting?.65:slicing||s.stage==='choose'?.16:.25)+Math.abs(Math.sin(a*3))*stir*.45;g.scale.setScalar(slicing&&s.slices>5?.8:1);g.rotation.y=i+stir*.7;g.rotation.z=stir*.2;if(g.userData.id===1)g.children[0].material=s.brown>.36?mushBrown:mushMat});steam.forEach((p,i)=>{const f=(time*.25+i*.13)%1;p.visible=!slicing;p.position.set(Math.sin(i*11)*1.4,.6+f*1.4,Math.cos(i*7)*1.2);p.scale.setScalar(.05+f*.16);p.material.opacity=.24*(1-f)});renderer.render(scene,camera);canvas.dataset.renderer='webgl'}requestAnimationFrame(animate);
}
